package com.ruoyi.framework.shiro.realm;

import com.ruoyi.common.constant.UserConstants;
import com.ruoyi.common.core.domain.entity.SysUser;
import com.ruoyi.system.service.ISysUserService;
import org.apache.shiro.authc.*;
import org.apache.shiro.authc.credential.HashedCredentialsMatcher;
import org.apache.shiro.realm.AuthorizingRealm;

public class UserRealm extends AuthorizingRealm {

    private final ISysUserService userService;

    public UserRealm(ISysUserService userService) {
        this.userService = userService;
        // 密码匹配器：MD5 散列 + 盐，与注册加密算法一致
        HashedCredentialsMatcher matcher = new HashedCredentialsMatcher("MD5");
        matcher.setHashIterations(2);
        setCredentialsMatcher(matcher);
    }

    @Override
    protected AuthenticationInfo doGetAuthenticationInfo(AuthenticationToken token) {
        String username = (String) token.getPrincipal();
        SysUser user = userService.selectUserByUserName(username);

        if (user == null) {
            throw new UnknownAccountException("账号或密码错误");
        }
        if (UserConstants.USER_DISABLE.equals(user.getStatus())) {
            throw new LockedAccountException("账号已停用");
        }
        // 第一个参数存 Principal（后续授权回调取用），第二个是密文
        return new SimpleAuthenticationInfo(user, user.getPassword(), getName());
    }
}

package com.ruoyi.framework.web.service;

import com.ruoyi.common.core.domain.entity.SysUser;
import com.ruoyi.common.core.domain.model.LoginUser;
import org.springframework.stereotype.Component;

@Component
public class SysLoginService {

    private final TokenService tokenService;
    private final SysPasswordService passwordService;
    private final SysPermissionService permissionService;

    public SysLoginService(TokenService tokenService,
                           SysPasswordService passwordService,
                           SysPermissionService permissionService) {
        this.tokenService = tokenService;
        this.passwordService = passwordService;
        this.permissionService = permissionService;
    }

    public String login(String username, String password) {
        // 查用户 + 锁定校验（UserDetailsServiceImpl 内部调用 passwordService.validate）
        SysUser user = userDetailsService.loadUserByUsername(username).getUser();

        // 密码比对，不匹配抛 UserPasswordNotMatchException
        passwordService.validate(user, password);

        // 登录时预计算权限集合（Shiro 版在授权回调里懒加载，这里改为一次性算好）
        var permissions = permissionService.getMenuPermission(user);
        LoginUser loginUser = new LoginUser(user.getUserId(), user.getDeptId(), user, permissions);

        // 签发 Token 并缓存到 Redis（详见 TokenService 一讲）
        return tokenService.createToken(loginUser);
    }
}
